import { describe, it, expect } from "vitest";

// Simulates a minimal package.json dependency map as it would be parsed at runtime
type DependencyMap = Record<string, string>;

interface PackageJson {
  dependencies?: DependencyMap;
  devDependencies?: DependencyMap;
}

const APM_PACKAGES = [
  "@opentelemetry/api",
  "@opentelemetry/sdk-node",
  "dd-trace",
  "newrelic",
  "@honeycombio/opentelemetry-node",
];

const ERROR_TRACKING_PACKAGES = [
  "@sentry/node",
  "@sentry/browser",
  "@sentry/nextjs",
  "rollbar",
  "bugsnag",
  "@bugsnag/js",
];

function detectObservabilityStack(pkg: PackageJson): {
  hasAPM: boolean;
  hasErrorTracking: boolean;
  missingObservability: boolean;
} {
  const allDeps = {
    ...pkg.dependencies,
    ...pkg.devDependencies,
  };

  const installedPackages = Object.keys(allDeps);

  const hasAPM = APM_PACKAGES.some((p) => installedPackages.includes(p));
  const hasErrorTracking = ERROR_TRACKING_PACKAGES.some((p) =>
    installedPackages.includes(p)
  );

  return {
    hasAPM,
    hasErrorTracking,
    missingObservability: !hasAPM || !hasErrorTracking,
  };
}

function simulateUnobservedError(
  pkg: PackageJson
): { caught: boolean; traceable: boolean; message: string } {
  const { hasAPM, hasErrorTracking } = detectObservabilityStack(pkg);

  // Simulate an error occurring in production
  const error = new Error("Database connection timeout after 30s");

  if (!hasErrorTracking) {
    // Error silently swallowed — no Sentry/Rollbar/Bugsnag to capture it
    return {
      caught: false,
      traceable: false,
      message: `Error lost: "${error.message}" — no error tracking configured`,
    };
  }

  if (!hasAPM) {
    return {
      caught: true,
      traceable: false,
      message: `Error captured but no distributed trace available for "${error.message}"`,
    };
  }

  return {
    caught: true,
    traceable: true,
    message: `Error captured and traceable: "${error.message}"`,
  };
}

describe("Observability stack detection", () => {
  it("demonstrates the foot-gun: a project with no observability deps loses errors silently", () => {
    const barePackageJson: PackageJson = {
      dependencies: {
        express: "^4.18.2",
        pg: "^8.11.0",
        lodash: "^4.17.21",
      },
      devDependencies: {
        typescript: "^5.0.0",
        vitest: "^1.0.0",
      },
    };

    const result = detectObservabilityStack(barePackageJson);

    // No APM and no error tracking — the worst case
    expect(result.hasAPM).toBe(false);
    expect(result.hasErrorTracking).toBe(false);
    expect(result.missingObservability).toBe(true);

    const errorOutcome = simulateUnobservedError(barePackageJson);
    expect(errorOutcome.caught).toBe(false);
    expect(errorOutcome.traceable).toBe(false);
    expect(errorOutcome.message).toContain("no error tracking configured");
  });

  it("demonstrates partial observability: error tracking without APM loses distributed traces", () => {
    const partialPackageJson: PackageJson = {
      dependencies: {
        express: "^4.18.2",
        "@sentry/node": "^7.80.0", // error tracking present
        // no APM
      },
    };

    const result = detectObservabilityStack(partialPackageJson);

    expect(result.hasAPM).toBe(false);
    expect(result.hasErrorTracking).toBe(true);
    // Still flagged as missing full observability
    expect(result.missingObservability).toBe(true);

    const errorOutcome = simulateUnobservedError(partialPackageJson);
    expect(errorOutcome.caught).toBe(true);
    expect(errorOutcome.traceable).toBe(false);
    expect(errorOutcome.message).toContain("no distributed trace available");
  });

  it("asserts the safe fix: project with Sentry + OpenTelemetry has full observability", () => {
    const instrumentedPackageJson: PackageJson = {
      dependencies: {
        express: "^4.18.2",
        pg: "^8.11.0",
        "@sentry/node": "^7.80.0",
        "@opentelemetry/api": "^1.7.0",
        "@opentelemetry/sdk-node": "^0.45.0",
      },
      devDependencies: {
        typescript: "^5.0.0",
        vitest: "^1.0.0",
      },
    };

    const result = detectObservabilityStack(instrumentedPackageJson);

    expect(result.hasAPM).toBe(true);
    expect(result.hasErrorTracking).toBe(true);
    expect(result.missingObservability).toBe(false);

    const errorOutcome = simulateUnobservedError(instrumentedPackageJson);
    expect(errorOutcome.caught).toBe(true);
    expect(errorOutcome.traceable).toBe(true);
    expect(errorOutcome.message).toContain("captured and traceable");
  });

  it("asserts the safe fix: Datadog APM + Sentry also satisfies full observability", () => {
    const datadogPackageJson: PackageJson = {
      dependencies: {
        "dd-trace": "^4.20.0",
        "@sentry/node": "^7.80.0",
        fastify: "^4.24.0",
      },
    };

    const result = detectObservabilityStack(datadogPackageJson);

    expect(result.hasAPM).toBe(true);
    expect(result.hasErrorTracking).toBe(true);
    expect(result.missingObservability).toBe(false);

    const errorOutcome = simulateUnobservedError(datadogPackageJson);
    expect(errorOutcome.caught).toBe(true);
    expect(errorOutcome.traceable).toBe(true);
  });
});

import { describe, it, expect } from "vitest";

// Synthetic simulation of a minimal analytics abstraction.
// We recreate the foot-gun (no telemetry = silent feature adoption)
// and the safe fix (a lightweight event-tracking shim with key lifecycle events).

// --- Foot-gun: no analytics layer ---
function createAppWithoutAnalytics() {
  const events: string[] = [];

  function onSignup(_userId: string) {
    // user signs up but nothing is tracked
  }

  function onActivation(_userId: string) {
    // user activates a feature but nothing is tracked
  }

  function onFirstValueMoment(_userId: string) {
    // user reaches first value moment but nothing is tracked
  }

  return { onSignup, onActivation, onFirstValueMoment, events };
}

// --- Safe fix: lightweight analytics shim tracking key lifecycle events ---
type AnalyticsEvent = {
  event: string;
  userId: string;
  properties?: Record<string, unknown>;
};

function createAnalyticsClient() {
  const captured: AnalyticsEvent[] = [];

  function capture(event: string, userId: string, properties?: Record<string, unknown>) {
    captured.push({ event, userId, properties });
  }

  return { capture, captured };
}

function createAppWithAnalytics(analytics: ReturnType<typeof createAnalyticsClient>) {
  function onSignup(userId: string) {
    analytics.capture("signup", userId);
  }

  function onActivation(userId: string) {
    analytics.capture("activation", userId, { feature: "core" });
  }

  function onFirstValueMoment(userId: string) {
    analytics.capture("first_value_moment", userId);
  }

  function onRetention(userId: string) {
    analytics.capture("retention", userId);
  }

  function onChurnSignal(userId: string, reason: string) {
    analytics.capture("churn_signal", userId, { reason });
  }

  return { onSignup, onActivation, onFirstValueMoment, onRetention, onChurnSignal };
}

describe("Product analytics telemetry", () => {
  it("demonstrates the foot-gun: no events are captured without an analytics layer", () => {
    const app = createAppWithoutAnalytics();

    app.onSignup("user-001");
    app.onActivation("user-001");
    app.onFirstValueMoment("user-001");

    // Without telemetry, we have zero visibility into user journeys.
    expect(app.events).toHaveLength(0);
    // There is no way to know how many users signed up, activated, or reached value.
    expect(app.events.find((e) => e === "signup")).toBeUndefined();
  });

  it("safe fix: key lifecycle events are captured and inspectable", () => {
    const analytics = createAnalyticsClient();
    const app = createAppWithAnalytics(analytics);

    app.onSignup("user-001");
    app.onActivation("user-001");
    app.onFirstValueMoment("user-001");
    app.onRetention("user-001");
    app.onChurnSignal("user-001", "price");

    expect(analytics.captured).toHaveLength(5);

    const eventNames = analytics.captured.map((e) => e.event);
    expect(eventNames).toContain("signup");
    expect(eventNames).toContain("activation");
    expect(eventNames).toContain("first_value_moment");
    expect(eventNames).toContain("retention");
    expect(eventNames).toContain("churn_signal");

    const churn = analytics.captured.find((e) => e.event === "churn_signal");
    expect(churn?.properties?.reason).toBe("price");

    const activation = analytics.captured.find((e) => e.event === "activation");
    expect(activation?.properties?.feature).toBe("core");

    // Every event is tied to a userId for journey analysis.
    analytics.captured.forEach((e) => {
      expect(e.userId).toBe("user-001");
    });
  });

  it("safe fix: multiple users produce independent event streams", () => {
    const analytics = createAnalyticsClient();
    const app = createAppWithAnalytics(analytics);

    app.onSignup("user-001");
    app.onSignup("user-002");
    app.onActivation("user-001");
    // user-002 never activates — a churn signal
    app.onChurnSignal("user-002", "no_activation");

    const user1Events = analytics.captured.filter((e) => e.userId === "user-001");
    const user2Events = analytics.captured.filter((e) => e.userId === "user-002");

    expect(user1Events.map((e) => e.event)).toEqual(["signup", "activation"]);
    expect(user2Events.map((e) => e.event)).toEqual(["signup", "churn_signal"]);

    // Activation rate: 1 out of 2 users activated
    const activatedUsers = new Set(
      analytics.captured.filter((e) => e.event === "activation").map((e) => e.userId)
    );
    expect(activatedUsers.size).toBe(1);
  });
});

import { describe, it, expect } from "vitest";

// Synthetic rate limiter implementations to demonstrate the foot-gun and the fix

interface AuthAttempt {
  ip: string;
  timestamp: number;
}

// FOOT-GUN: Auth handler with NO rate limiting
function createUnprotectedAuthHandler() {
  const successfulLogins: string[] = [];

  function login(ip: string, password: string): { success: boolean; token?: string } {
    // No rate limiting — every attempt is processed
    if (password === "correct-password") {
      successfulLogins.push(ip);
      return { success: true, token: "jwt-token-abc123" };
    }
    return { success: false };
  }

  return { login, successfulLogins };
}

// SAFE FIX: Auth handler WITH rate limiting (5 attempts/min per IP) and account locking (10 failures)
function createRateLimitedAuthHandler(options: { maxAttemptsPerMinute: number; lockAfterFailures: number }) {
  const attemptLog = new Map<string, AuthAttempt[]>();
  const lockedAccounts = new Set<string>();
  const failureCount = new Map<string, number>();

  function isRateLimited(ip: string, now: number): boolean {
    const windowMs = 60_000;
    const attempts = attemptLog.get(ip) ?? [];
    const recentAttempts = attempts.filter((a) => now - a.timestamp < windowMs);
    attemptLog.set(ip, recentAttempts);
    return recentAttempts.length >= options.maxAttemptsPerMinute;
  }

  function recordAttempt(ip: string, now: number): void {
    const attempts = attemptLog.get(ip) ?? [];
    attempts.push({ ip, timestamp: now });
    attemptLog.set(ip, attempts);
  }

  function login(
    ip: string,
    username: string,
    password: string,
    now: number = Date.now()
  ): { success: boolean; token?: string; error?: string } {
    if (lockedAccounts.has(username)) {
      return { success: false, error: "account_locked" };
    }

    if (isRateLimited(ip, now)) {
      return { success: false, error: "rate_limited" };
    }

    recordAttempt(ip, now);

    if (password === "correct-password") {
      failureCount.set(username, 0);
      return { success: true, token: "jwt-token-abc123" };
    }

    const failures = (failureCount.get(username) ?? 0) + 1;
    failureCount.set(username, failures);

    if (failures >= options.lockAfterFailures) {
      lockedAccounts.add(username);
      return { success: false, error: "account_locked" };
    }

    return { success: false, error: "invalid_credentials" };
  }

  return { login, lockedAccounts, failureCount };
}

describe("Auth Endpoints Not Rate Limited", () => {
  it("demonstrates the foot-gun: unprotected handler allows unlimited brute-force attempts", () => {
    const handler = createUnprotectedAuthHandler();
    const attackerIp = "192.168.1.100";
    const passwords = Array.from({ length: 100 }, (_, i) => `guess-${i}`);
    passwords.push("correct-password");

    let successResult: { success: boolean; token?: string } | null = null;
    let totalAttempts = 0;

    for (const pwd of passwords) {
      totalAttempts++;
      const result = handler.login(attackerIp, pwd);
      if (result.success) {
        successResult = result;
        break;
      }
    }

    // Without rate limiting, all 101 attempts go through unimpeded
    expect(totalAttempts).toBe(101);
    expect(successResult).not.toBeNull();
    expect(successResult?.success).toBe(true);
    expect(successResult?.token).toBe("jwt-token-abc123");
    // No protection was applied — attacker succeeded after exhaustive guessing
  });

  it("safe fix: rate limiter blocks more than 5 attempts per minute from the same IP", () => {
    const handler = createRateLimitedAuthHandler({ maxAttemptsPerMinute: 5, lockAfterFailures: 10 });
    const attackerIp = "192.168.1.100";
    const baseTime = 1_000_000;

    const results = Array.from({ length: 8 }, (_, i) =>
      handler.login(attackerIp, "victim", `guess-${i}`, baseTime + i * 100)
    );

    // First 5 attempts should be processed (wrong password)
    for (let i = 0; i < 5; i++) {
      expect(results[i].error).toBe("invalid_credentials");
    }

    // Attempts 6-8 should be rate limited
    for (let i = 5; i < 8; i++) {
      expect(results[i].error).toBe("rate_limited");
      expect(results[i].success).toBe(false);
    }
  });

  it("safe fix: account locking triggers after 10 consecutive failures", () => {
    const handler = createRateLimitedAuthHandler({ maxAttemptsPerMinute: 100, lockAfterFailures: 10 });
    const ip = "10.0.0.1";
    const username = "target-user";
    const baseTime = 2_000_000;

    // Simulate 10 failed attempts (spread across time to avoid rate limit)
    const results = Array.from({ length: 10 }, (_, i) =>
      handler.login(ip, username, `wrong-${i}`, baseTime + i * 10_000)
    );

    // First 9 should return invalid_credentials
    for (let i = 0; i < 9; i++) {
      expect(results[i].error).toBe("invalid_credentials");
    }

    // 10th attempt triggers account lock
    expect(results[9].error).toBe("account_locked");
    expect(handler.lockedAccounts.has(username)).toBe(true);

    // Subsequent attempts — even with correct password — are blocked
    const afterLock = handler.login(ip, username, "correct-password", baseTime + 200_000);
    expect(afterLock.success).toBe(false);
    expect(afterLock.error).toBe("account_locked");
  });

  it("safe fix: legitimate user can still log in within the rate limit window", () => {
    const handler = createRateLimitedAuthHandler({ maxAttemptsPerMinute: 5, lockAfterFailures: 10 });
    const ip = "203.0.113.42";
    const baseTime = 3_000_000;

    // Two failed attempts then a correct one — all within limit
    const fail1 = handler.login(ip, "alice", "wrong1", baseTime);
    const fail2 = handler.login(ip, "alice", "wrong2", baseTime + 1000);
    const success = handler.login(ip, "alice", "correct-password", baseTime + 2000);

    expect(fail1.error).toBe("invalid_credentials");
    expect(fail2.error).toBe("invalid_credentials");
    expect(success.success).toBe(true);
    expect(success.token).toBe("jwt-token-abc123");
  });
});
